CREATE TABLE IF NOT EXISTS schema_migrations(version VARCHAR(80) PRIMARY KEY,applied_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS print_jobs(id BIGINT AUTO_INCREMENT PRIMARY KEY,printer_id VARCHAR(64) NULL,kind VARCHAR(40) NOT NULL,payload LONGTEXT NOT NULL,printer_snapshot LONGTEXT NULL,dedupe_key VARCHAR(180) UNIQUE,status ENUM('queued','sending','sent','failed','uncertain','blocked') NOT NULL DEFAULT 'queued',attempts INT NOT NULL DEFAULT 0,next_attempt DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,last_error VARCHAR(500),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,sent_at DATETIME NULL,INDEX ix_print_queue(status,next_attempt));
CREATE TABLE IF NOT EXISTS kitchen_tickets(id BIGINT AUTO_INCREMENT PRIMARY KEY,pedido_id INT NOT NULL,payload LONGTEXT NOT NULL,status ENUM('pending','preparing','ready','done','cancelled') DEFAULT 'pending',version INT DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX ix_kitchen_status(status),FOREIGN KEY(pedido_id) REFERENCES pedidos(id));
CREATE TABLE IF NOT EXISTS operation_keys(operation_key VARCHAR(160) PRIMARY KEY,request_hash CHAR(64) NOT NULL,response LONGTEXT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS audit_events(id BIGINT AUTO_INCREMENT PRIMARY KEY,actor VARCHAR(120) NOT NULL,action VARCHAR(80) NOT NULL,entity_id VARCHAR(80),details LONGTEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
ALTER TABLE pedidos ADD COLUMN IF NOT EXISTS version INT NOT NULL DEFAULT 1;
INSERT IGNORE INTO schema_migrations(version) VALUES('002_integrations');

ALTER TABLE pedidos ADD COLUMN IF NOT EXISTS migrated_legacy BOOLEAN NOT NULL DEFAULT FALSE;
CREATE TABLE IF NOT EXISTS notification_jobs(id BIGINT AUTO_INCREMENT PRIMARY KEY,event_key VARCHAR(150) NOT NULL UNIQUE,recipient VARCHAR(30) NOT NULL,message TEXT NOT NULL,status ENUM('queued','sent','failed') DEFAULT 'queued',attempts INT DEFAULT 0,next_attempt DATETIME DEFAULT CURRENT_TIMESTAMP,last_error VARCHAR(500),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
